function vpsSeedPrice(value){
 if(value==null||value==='')return null;
 if(typeof value==='number')return Number.isFinite(value)?value:null;
 const raw=String(value).trim(); if(!raw||/tidak ada harga|tidak tersedia|n\/a/i.test(raw))return null;
 const n=Number(raw.replace(/rp\.?/ig,'').replace(/\./g,'').replace(/,/g,'.').replace(/[^0-9.-]/g,''));
 return Number.isFinite(n)?n:null;
}

function vpsIsVarioVehicle(vehicle){return !!vehicle&&String(vehicle.modelId||'').toLowerCase()===VEHICLE_PART_SOT_MODEL_ID;}
function vpsCategoryList(items){const m=new Map();(items||[]).forEach(it=>{const c=String(it.category||'').trim();if(c&&!m.has(c))m.set(c,{id:'vcat_'+slugify(c),name:c});});return [...m.values()];}
function vpsSubcategoryList(items,cat){const m=new Map();(items||[]).filter(it=>!cat||it.category===cat).forEach(it=>{const s=String(it.subcategory||'').trim();if(s&&!m.has(s))m.set(s,{id:'vsub_'+slugify(cat||'all')+'_'+slugify(s),name:s});});return [...m.values()];}
async function vpsEnsureSeeded(){
 if(typeof VehicleCatalog==='undefined')return {success:false,reason:'VehicleCatalog unavailable'};
 await VehicleCatalog.ensureLoaded();
 const all=await VehicleCatalog.getAll();
 const by=new Map(all.map(it=>[vpsNormCode(it.oemCode),it]));
 let created=0,updated=0;
 for(const seed of VEHICLE_PART_SOT_SEED){
   const key=vpsNormCode(seed.oemCode); if(!key)continue;
   const existing=by.get(key);
   if(!existing){const seedData={...seed,price:vpsSeedPrice(seed.price),compatibleModelIds:[VEHICLE_PART_SOT_MODEL_ID]};const res=await VehicleCatalog.create(seedData);if(res&&res.success){by.set(key,res.item);created++;}}
   else {
     const patch={category:seed.category,subcategory:seed.subcategory,compatibleVehicleIds:Array.from(new Set([...(existing.compatibleVehicleIds||[]),...(seed.compatibleVehicleIds||[])])),compatibleModelIds:Array.from(new Set([...(existing.compatibleModelIds||[]),VEHICLE_PART_SOT_MODEL_ID]))};
     if(seed.aliases)patch.aliases=Array.from(new Set([...(existing.aliases||[]),...seed.aliases]));
     const needs=existing.category!==patch.category||existing.subcategory!==patch.subcategory||JSON.stringify(existing.compatibleVehicleIds||[])!==JSON.stringify(patch.compatibleVehicleIds||[])||(seed.aliases&&JSON.stringify(existing.aliases||[])!==JSON.stringify(patch.aliases));
     if(needs){const res=await VehicleCatalog.update(existing.id,patch);if(res&&res.success){by.set(key,res.item);updated++;}}
   }
 }
 return {success:true,created,updated,count:by.size};
}
function vpsItemsForCurrentVehicle(items){
 const list=Array.isArray(items)?items:[];
 const vid=typeof curVehicleId!=='undefined'?curVehicleId:null;
 const veh=typeof D!=='undefined'&&Array.isArray(D.vehicles)?D.vehicles.find(v=>sameId(v.id,vid)):null;
 if(!vpsIsVarioVehicle(veh))return [];
 return list.filter(it=>{
   const direct=Array.isArray(it.compatibleVehicleIds)&&it.compatibleVehicleIds.some(id=>sameId(id,vid));
   const model=Array.isArray(it.compatibleModelIds)&&it.compatibleModelIds.some(id=>String(id)===VEHICLE_PART_SOT_MODEL_ID);
   return direct||model;
 });
}
function vpsEnsureVehicleFinanceSubs(items){
 if(typeof D==='undefined'||!D.categories||!Array.isArray(D.categories.expense))return;
 const vid=typeof curVehicleId!=='undefined'?curVehicleId:null;
 const veh=Array.isArray(D.vehicles)?D.vehicles.find(v=>sameId(v.id,vid)):null;
 if(!vpsIsVarioVehicle(veh))return;
 let cat=D.categories.expense.find(c=>c.linkedVehicleId===vid)||D.categories.expense.find(c=>c.name&&c.name.trim().toLowerCase()===String(veh.name||'').trim().toLowerCase());
 if(!cat)return;
 cat.linkedVehicleId=vid;cat.subs=Array.isArray(cat.subs)?cat.subs:[];
 const names=['Bensin','Servis & Oli','Pajak',...vpsCategoryList(items).map(x=>x.name)];
 let changed=false;
 names.forEach(name=>{if(!cat.subs.some(s=>String(s.name||'').trim().toLowerCase()===name.trim().toLowerCase())){cat.subs.push({id:'sub_'+slugify(name)+'_'+uid(),name});changed=true;}});
 if(changed&&typeof save==='function')save();
}
function vpsPartLabel(it){return `${it.partName||'(Tanpa nama)'}${it.oemCode?' — '+it.oemCode:''}`;}
function vpsNormCode(v){return String(v==null?'':v).trim().toLowerCase().replace(/[\s-]/g,'');}
function vpsCatalogCandidatesForSparepartCat(cat,items,vehicleId){
 const list=Array.isArray(items)?items:[]; const c=cat||{};
 const vid=vehicleId||c.vehicleId||null;
 const compatible=list.filter(it=>{
   if(!vid)return true;
   return Array.isArray(it.compatibleVehicleIds)&&it.compatibleVehicleIds.some(id=>sameId(id,vid));
 });
 const code=vpsNormCode(c.code);
 if(code){
   const byCode=compatible.filter(it=>vpsNormCode(it.oemCode)===code);
   if(byCode.length)return byCode;
 }
 const name=String(c.name||'').trim().toLowerCase();
 if(!name)return [];
 return compatible.filter(it=>String(it.partName||'').trim().toLowerCase()===name);
}
function vpsResolveSparepartCategory(cat,items,vehicleId){
 const candidates=vpsCatalogCandidatesForSparepartCat(cat,items,vehicleId);
 if(candidates.length!==1)return {linked:false,ambiguous:candidates.length>1,part:null};
 const part=candidates[0];
 return {linked:true,ambiguous:false,part};
}
async function vpsMigrateLegacySparepartCats(){
 if(typeof D==='undefined'||!D||!Array.isArray(D.sparepartCats)||typeof VehicleCatalog==='undefined')return {ok:true,changed:0,linked:0,ambiguous:0,unmatched:0};
 await vpsEnsureSeeded();
 const items=await VehicleCatalog.getAll(); let changed=0,linked=0,ambiguous=0,unmatched=0;
 D.sparepartCats.forEach(cat=>{
   if(!cat||cat.catalogPartId)return;
   const r=vpsResolveSparepartCategory(cat,items,cat.vehicleId||null);
   if(r.linked){cat.catalogPartId=r.part.id;linked++;changed++;}
   else if(r.ambiguous)ambiguous++; else unmatched++;
 });
 if(changed&&typeof save==='function')save();
 return {ok:true,changed,linked,ambiguous,unmatched};
}
async function vpsAuditSparepartCategoryLinks(){
 if(typeof D==='undefined'||!Array.isArray(D.sparepartCats)||typeof VehicleCatalog==='undefined')return {ok:true,total:0,linked:0,unlinked:0,invalid:0,ambiguous:0};
 await vpsEnsureSeeded(); const items=await VehicleCatalog.getAll(); let linked=0,unlinked=0,invalid=0,ambiguous=0;
 D.sparepartCats.forEach(cat=>{
   if(!cat)return;
   if(cat.catalogPartId){const hit=items.find(it=>sameId(it.id,cat.catalogPartId));if(hit)linked++;else invalid++;return;}
   const r=vpsResolveSparepartCategory(cat,items,cat.vehicleId||null);
   if(r.ambiguous)ambiguous++; else unlinked++;
 });
 return {ok:true,total:D.sparepartCats.length,linked,unlinked,invalid,ambiguous};
}
function vpsGetCatalogPartForSparepartCategory(cat,items,vehicleId){
 if(!cat)return null;
 const list=Array.isArray(items)?items:((typeof VehicleCatalog!=='undefined'&&VehicleCatalog.getStore)?VehicleCatalog.getStore().items||[]:[]);
 if(cat.catalogPartId){const hit=list.find(it=>sameId(it.id,cat.catalogPartId));if(hit)return hit;}
 const r=vpsResolveSparepartCategory(cat,list,vehicleId||cat.vehicleId||null);
 return r.linked?r.part:null;
}

async function vpsGetItems(){await vpsEnsureSeeded();const all=await VehicleCatalog.getAll();try{await vpsMigrateLegacySparepartCats();}catch(e){console.warn('[VehiclePartSOT] legacy sparepart category migration skipped',e);}return vpsItemsForCurrentVehicle(all);}

async function vpsMountTxPicker(selectedId){
 const anchor=document.getElementById('txSubWrap'); if(!anchor)return;
 const veh=typeof D!=='undefined'&&Array.isArray(D.vehicles)?D.vehicles.find(v=>sameId(v.id,typeof curVehicleId!=='undefined'?curVehicleId:null)):null;
 if(!vpsIsVarioVehicle(veh)||curTxType!=='expense'){const old=document.getElementById('txVehiclePartSotWrap');if(old)old.remove();return;}
 const items=await vpsGetItems();vpsEnsureVehicleFinanceSubs(items);
 let wrap=document.getElementById('txVehiclePartSotWrap');
 if(!wrap){wrap=document.createElement('div');wrap.id='txVehiclePartSotWrap';wrap.className='fg';anchor.insertAdjacentElement('afterend',wrap);}
 const cats=vpsCategoryList(items); const current=selectedId||wrap.dataset.selectedId||'';
 wrap.innerHTML='<label class="fl">Komponen Vario 125 KZR <span style="font-weight:400;text-transform:none;letter-spacing:0;color:var(--text3)">(SOT katalog)</span></label><select class="fs" id="txVehiclePartCategory"></select><select class="fs" id="txVehiclePartSubcategory" style="margin-top:7px"></select><select class="fs" id="txVehiclePartId" style="margin-top:7px"></select><div id="txVehiclePartSotHint" style="font-size:11px;color:var(--text2);margin-top:5px"></div>';
 const cs=document.getElementById('txVehiclePartCategory'),ss=document.getElementById('txVehiclePartSubcategory'),ps=document.getElementById('txVehiclePartId');
 const saved=items.find(it=>String(it.id)===String(current)); const cat0=saved?saved.category:(cats[0]&&cats[0].name)||'';
 cs.innerHTML='<option value="">Pilih kategori part</option>'+cats.map(c=>`<option value="${escapeHtml(c.name)}">${escapeHtml(c.name)}</option>`).join('');cs.value=cat0;
 function fillSub(){const subs=vpsSubcategoryList(items,cs.value);const old=saved?saved.subcategory:wrap.dataset.sub||'';ss.innerHTML='<option value="">Pilih subkategori</option>'+subs.map(s=>`<option value="${escapeHtml(s.name)}">${escapeHtml(s.name)}</option>`).join('');ss.value=subs.some(s=>s.name===old)?old:'';fillParts();}
 function fillParts(){const list=items.filter(it=>(!cs.value||it.category===cs.value)&&(!ss.value||it.subcategory===ss.value));const keep=ps.value||current;ps.innerHTML='<option value="">Tidak mengaitkan part katalog</option>'+list.map(it=>`<option value="${escapeHtml(it.id)}">${escapeHtml(vpsPartLabel(it))}</option>`).join('');if(list.some(it=>String(it.id)===String(keep)))ps.value=keep;wrap.dataset.selectedId=ps.value||'';wrap.dataset.sub=ss.value||'';const hit=list.find(it=>String(it.id)===String(ps.value));document.getElementById('txVehiclePartSotHint').textContent=hit&&hit.price!=null?'Harga katalog referensi: Rp '+Number(hit.price).toLocaleString('id-ID'):'';}
 cs.onchange=()=>{fillSub();};ss.onchange=()=>{fillParts();};ps.onchange=()=>{wrap.dataset.selectedId=ps.value||'';fillParts();};
 fillSub();
}
function vpsReadTxSelection(){const id=document.getElementById('txVehiclePartId')?.value||'';return id||null;}
function vpsApplyTxSnapshot(tx){if(!tx)return;const id=vpsReadTxSelection();if(!id){delete tx.vehicleCatalogPartId;delete tx.vehicleCatalogCategory;delete tx.vehicleCatalogSubcategory;delete tx.vehicleCatalogPartName;delete tx.vehicleCatalogPartCode;return;}const item=(VehicleCatalog.getStore().items||[]).find(x=>String(x.id)===String(id));if(!item)return;tx.vehicleCatalogPartId=item.id;tx.vehicleCatalogCategory=item.category||'';tx.vehicleCatalogSubcategory=item.subcategory||'';tx.vehicleCatalogPartName=item.partName||'';tx.vehicleCatalogPartCode=item.oemCode||'';}
function vpsRestoreTxSelection(tx){const id=tx&&tx.vehicleCatalogPartId;return vpsMountTxPicker(id);}

async function vpsEnhanceServiceCatalogSelect(){
 const sel=document.getElementById('servisCatalogPartId');if(!sel||typeof VehicleCatalog==='undefined')return;
 await vpsEnsureSeeded();const all=await VehicleCatalog.getAll();const list=vpsItemsForCurrentVehicle(all);const cur=sel.value;
 const groups=new Map();list.forEach(it=>{const k=it.category+'\u0000'+(it.subcategory||'Lainnya');if(!groups.has(k))groups.set(k,{cat:it.category,sub:it.subcategory||'Lainnya',items:[]});groups.get(k).items.push(it);});
 sel.innerHTML='<option value="">Tidak pakai part katalog</option>'+[...groups.values()].map(g=>`<optgroup label="${escapeHtml(g.cat+' › '+g.sub)}">${g.items.map(it=>`<option value="${escapeHtml(it.id)}" data-oem="${escapeHtml(it.oemCode||'')}" data-name="${escapeHtml(it.partName||'')}">${escapeHtml(vpsPartLabel(it))}</option>`).join('')}</optgroup>`).join('');
 if(cur&&list.some(it=>String(it.id)===String(cur)))sel.value=cur;
 if(typeof Servis!=='undefined'&&typeof Servis.onCatalogPartChange==='function')Servis.onCatalogPartChange();
}

const VehiclePartSOT={version:VEHICLE_PART_SOT_VERSION,seed:VEHICLE_PART_SOT_SEED,ensureSeeded:vpsEnsureSeeded,getItems:vpsGetItems,categories:async()=>vpsCategoryList(await vpsGetItems()),subcategories:async c=>vpsSubcategoryList(await vpsGetItems(),c),mountTxPicker:vpsMountTxPicker,readTxSelection:vpsReadTxSelection,applyTxSnapshot:vpsApplyTxSnapshot,restoreTxSelection:vpsRestoreTxSelection,enhanceServiceCatalogSelect:vpsEnhanceServiceCatalogSelect,migrateLegacySparepartCats:vpsMigrateLegacySparepartCats,auditSparepartCategoryLinks:vpsAuditSparepartCategoryLinks,getCatalogPartForSparepartCategory:vpsGetCatalogPartForSparepartCategory};
if(typeof window!=='undefined')window.VehiclePartSOT=VehiclePartSOT;

